void setUp(void) {}
void tearDown(void) {}

#ifdef HAVE_ROM
using marble_physics::Mem;
using marble_physics::PLAYER;

// object fields
static const uint8_t PX = 0x0c, PY = 0x10, PZ = 0x14, SLOT = 0x18, IDX = 0x19, ZONE = 0x1b;
static const uint8_t VISIBLE = 0x1c, SX = 0x1e, SY = 0x20, MASKS = 0x38, SCORE = 0xbc;
static const uint8_t ANIM = 0x5a, SHARDS = 0x62, SHARDS_ON = 0x67;
static const uint8_t N_KIND = 0x1a, N_STEPS = 0x1b, N_ANIM = 0x1c, N_SCREEN = 0x20;
static const uint8_t N_TICK = 0x24, N_TYPE = 0x25, N_DIR = 0x26;
static const uint8_t MASK_BYTES = 30;
static const uint32_t RNG = 0x4003a6;
static const uint16_t RNG_TICK = 0x100;
static const uint32_t LIST = 0x4003bc, ENTRIES = 0x4001dc;  // draw list bytes, entries
static const uint8_t ENTRY_SIZE = 14, LIST_MAX = 31, LIST_END = 0xff;
static const uint8_t RACES = 6, RACE_SILLY = 4;
static const int8_t BAND_LO = 0x1d, BAND_HI = 0x38;  // mini band
static const int16_t SWEEP_STEP = 4;                 // marble_mo.SWEEP_STEP
static const uint8_t COLLECTED = 2, ACID = 9;

static uint8_t ram[marble_physics::RAM_SIZE];

static uint32_t mini(uint8_t i) { return marble_enemies::MINIS + marble_enemies::MINI_SIZE * i; }

static void loadRam(const MarbleMiniSegment &seg) {
  memset(ram, 0, sizeof(ram));
  for (uint8_t i = 0; i < seg.nram; i++) {
    const MarbleMiniRam &r = seg.ram[i];
    memcpy(ram + (r.addr - marble_physics::RAM_BASE), r.bytes, r.len);
  }
}

// draw list entry k in link order: type << 8 | index, -1 past the end
static int16_t entryAt(const Mem &m, uint8_t k) {
  if (k >= LIST_MAX || m.rb(LIST + k) == LIST_END) { return -1; }
  const uint32_t e = ENTRIES + ENTRY_SIZE * m.rb(LIST + k);
  return (int16_t)(m.rb(e) << 8 | m.rb(e + 1));
}

static uint8_t listedCount(const Mem &m, uint8_t type, uint8_t idx) {
  uint8_t n = 0;
  for (uint8_t k = 0; entryAt(m, k) >= 0; k++) { n += entryAt(m, k) == (type << 8 | idx); }
  return n;
}

// player frame header drawn from +0x5a (states 1, 2, 5, 9) and the shard overlay +0x62
static uint32_t playerHdr(const Mem &m) {
  const uint8_t st = marble_physics::state(m);
  const bool drawn = st == marble_physics::DIZZY || st == marble_physics::BROKEN ||
                     st == marble_physics::EATEN || st == marble_physics::DISSOLVING;
  return m.rb(PLAYER + VISIBLE) && drawn ? m.roml(m.rl(PLAYER + ANIM)) : 0;
}

static uint32_t shardHdr(const Mem &m) {
  return m.rb(PLAYER + VISIBLE) && m.rb(PLAYER + SHARDS_ON) ? m.roml(m.rl(PLAYER + SHARDS)) : 0;
}

static const char *playerDiff(const Mem &m, const MarbleMiniTick &t) {
  if (marble_physics::x(m) != t.x) { return "player x"; }
  if (marble_physics::y(m) != t.y) { return "player y"; }
  if (marble_physics::z(m) != t.z) { return "player z"; }
  if (marble_physics::state(m) != t.state) { return "player state"; }
  if (m.rb(PLAYER + VISIBLE) != t.vis) { return "player vis"; }
  if (m.sw(PLAYER + SX) != t.sx || m.sw(PLAYER + SY) != t.sy) { return "player sx/sy"; }
  if (m.rl(PLAYER + ANIM) != t.anim) { return "player anim"; }
  if (playerHdr(m) != t.frame_hdr) { return "player frame"; }
  if (shardHdr(m) != t.shard_hdr) { return "player shards"; }
  if (memcmp(ram + (PLAYER + MASKS - marble_physics::RAM_BASE), t.mask, MASK_BYTES)) {
    return "player mask";
  }
  if (m.rw(RNG) != t.rng) { return "rng"; }
  return nullptr;
}

// mini frame drawn: rl(anim cursor) while live and listed, else 0
static uint32_t miniHdr(const Mem &m, uint8_t i) {
  const uint32_t a = mini(i);
  return m.rb(a + SLOT) && listedCount(m, m.rb(a + N_TYPE), i) ? m.roml(m.rl(a + N_ANIM)) : 0;
}

static const char *miniDiff(const Mem &m, uint8_t i, const MarbleMiniObj &s) {
  const uint32_t a = mini(i);
  if (m.rb(a + SLOT) != s.live) { return "mini live"; }
  if (m.rb(a + N_KIND) != s.kind) { return "mini kind"; }
  if (m.rb(a + N_TYPE) != s.type) { return "mini type"; }
  if (m.sl(a + PX) != s.x || m.sl(a + PY) != s.y) { return "mini x/y"; }
  if (m.sl(a + PZ) != s.z) { return "mini z"; }
  if (m.sw(a + N_SCREEN) != s.sx || m.sw(a + N_SCREEN + 2) != s.sy) { return "mini sx/sy"; }
  if (m.rb(a + N_TICK) != s.tick) { return "mini tick"; }
  if (m.rb(a + N_STEPS) != s.steps) { return "mini steps"; }
  if (m.rl(a + N_ANIM) != s.cursor) { return "mini cursor"; }
  if (m.rb(a + N_DIR) != s.dir) { return "mini dir"; }
  if (m.sl(a) != s.vx || m.sl(a + 4) != s.vy) { return "mini v"; }
  if (miniHdr(m, i) != s.frame_hdr) { return "mini frame"; }
  return nullptr;
}

static const char *listDiff(const Mem &m, const MarbleMiniSegment &seg, const MarbleMiniTick &t) {
  for (uint8_t k = 0; k < t.nlist; k++) {
    const MarbleMiniEntry &e = seg.list[t.lfirst + k];
    if (entryAt(m, k) != (e.type << 8 | e.index)) { return "draw list"; }
  }
  return entryAt(m, t.nlist) < 0 ? nullptr : "draw list length";
}

// One main loop tick as marble_mini.py replays it: 0x400010 and the camera long are inputs,
// then 0x1344c, band spawns (old camera still stored, as 0x13ee6), player 0x251de, every
// enemy, slots 0x12fd0, rng, the 0x26f3e sort.
static void mainTick(Mem &m, int8_t c6, int8_t c7, uint32_t camera, uint32_t frames) {
  m.wl(marble_physics::FRAMES, frames);
  marble_objects::applyQueued(m);
  const int16_t old = m.sw(marble_physics::CAMERA);
  if ((int16_t)camera != old) { marble_objects::cameraBands(m, old, (int16_t)camera); }
  m.wl(marble_physics::CAMERA_L, camera);
  marble_physics::tick(m, c6, c7);
  marble_enemies::update(m);
  marble_objects::update(m);
  marble_rng::rng(m, RNG_TICK);
  marble_drawlist::sort(m);
}

static void test_replay_minis(void) {
  for (uint8_t s = 0; s < MARBLE_MINI_SEGMENTS; s++) {
    const MarbleMiniSegment &seg = marble_mini_segments[s];
    loadRam(seg);
    Mem m(ram, seg.race);

    for (uint16_t k = 0; k < seg.nticks; k++) {
      const MarbleMiniTick &t = seg.ticks[k];
      mainTick(m, t.c6, t.c7, t.camera, t.frames);
      const char *bad = playerDiff(m, t);
      int8_t which = -1;
      for (uint8_t i = 0; i < marble_enemies::NMINIS && !bad; i++) {
        bad = miniDiff(m, i, t.m[i]);
        which = (int8_t)i;
      }
      if (!bad) {
        which = -1;
        bad = listDiff(m, seg, t);
      }
      if (!bad) { continue; }

      char msg[160];
      snprintf(msg, sizeof(msg), "segment %d (race %d frame %u) tick %d: mini %d %s differs", s,
               seg.race, (unsigned)seg.frame, k, which, bad);
      TEST_FAIL_MESSAGE(msg);
    }
  }
}

// ---------------------------------------------------------------- mini objects

// One MO as the published state draws it: race pixel top left, height, hflip
struct DrawnMo {
  int16_t x, top;
  uint8_t h;
  bool flip;
};

static const uint8_t MOS_MAX = 16;          // frame columns of one mini
static const uint8_t PAL[3] = {5, 6, 4};    // MO palette set of types 7, 8, 9

// mini j live and listed with the same screen position and frame as mini i (same object)
static bool twin(const Mem &m, uint8_t i, uint8_t j) {
  const uint32_t a = mini(i), b = mini(j);
  return m.rb(b + SLOT) && m.rb(b + N_TYPE) == m.rb(a + N_TYPE) &&
         listedCount(m, m.rb(b + N_TYPE), j) && m.rl(b + N_SCREEN) == m.rl(a + N_SCREEN) &&
         m.roml(m.rl(b + N_ANIM)) == m.roml(m.rl(a + N_ANIM));
}

// MOs of mini i in v: its object (frame rl(+0x1c), palette of its type) at the origin
// (+0x20, top + ARCADE_H - +0x22); minis on the same spot with the same frame by index order
static uint8_t miniMos(const Mem &m, const marble_video::VideoState &v, uint8_t i, int16_t top,
                       DrawnMo *out) {
  using namespace marble_video;
  const uint32_t a = mini(i);
  if (!m.rb(a + SLOT)) { return 0; }
  const int16_t ox = m.sw(a + N_SCREEN);
  const int16_t oy = (int16_t)(top + ARCADE_H - m.sw(a + N_SCREEN + 2));
  const MarbleSpriteSet &ds = marble_physics::deathSet();
  const uint8_t frame = marble_physics::deathFrame(m.roml(m.rl(a + N_ANIM)));
  const uint8_t set = SET_DEATH | (uint8_t)(SET_MINI + m.rb(a + N_TYPE) - 7);
  uint8_t skip = 0;
  for (uint8_t j = 0; j < i; j++) { skip += twin(m, i, j); }
  uint8_t k = 0;
  for (uint8_t j = 0; j < v.n; j++) {
    const Obj &o = v.objs[j];
    if (o.x != ox || o.y != oy || o.set != set || o.frame != frame) { continue; }
    if (skip) {
      skip--;
      continue;
    }
    TEST_ASSERT_EQUAL_UINT8(0, o.nmask);
    const MarbleSpriteFrame &f = ds.frames[o.frame];
    for (uint8_t c = 0; c < f.ncols && k < MOS_MAX; c++) {
      const MarbleSpriteCol &col = ds.cols[f.first + c];
      out[k++] = {(int16_t)(o.x + col.x), (int16_t)(o.y + col.y), (uint8_t)(col.h & 0x7f),
                  (col.h & 0x80) != 0};
    }
    break;
  }
  return k;
}

// Published minis (build at the arcade cull) against the mini MOs MAME emitted in every
// fixture tick: frame columns (position, height, flip, palette set of the type)
static void test_mini_objects(void) {
  uint16_t drawn = 0, dropped = 0;
  for (uint8_t sg = 0; sg < MARBLE_MINI_SEGMENTS; sg++) {
    const MarbleMiniSegment &seg = marble_mini_segments[sg];
    loadRam(seg);
    Mem m(ram, seg.race);
    const int16_t descTop = (int16_t)m.romw(m.desc() + marble_physics::DESC_TOP);

    for (uint16_t k = 0; k < seg.nticks; k++) {
      const MarbleMiniTick &t = seg.ticks[k];
      mainTick(m, t.c6, t.c7, t.camera, t.frames);
      marble_video::VideoState v = {};
      v.level = seg.race;
      marble_drawlist::build(m, (int16_t)t.camera, 0, v);
      const int16_t top = (int16_t)((int16_t)t.camera - descTop);

      for (uint8_t i = 0; i < marble_enemies::NMINIS; i++) {
        const MarbleMiniObj &s = t.m[i];
        char msg[100];
        snprintf(msg, sizeof(msg), "segment %d tick %d mini %d (kind %d)", sg, k, i, s.kind);
        DrawnMo got[MOS_MAX];
        const uint8_t n = miniMos(m, v, i, top, got);
        if (v.n == marble_video::OBJS && n < s.n) {  // published list full: dropped
          dropped++;
          continue;
        }
        TEST_ASSERT_EQUAL_UINT8_MESSAGE(s.n, n, msg);
        for (uint8_t j = 0; j < n; j++) {
          const MarbleMiniMo &e = seg.mos[s.first + j];
          const uint16_t y = (uint16_t)(top + 256 - got[j].top - 8 * got[j].h);
          const uint16_t x = (uint16_t)(got[j].x + 24);
          TEST_ASSERT_EQUAL_HEX16_MESSAGE(e.w0, ((y << 5) & 0x3fe0) | (got[j].flip ? 0x8000 : 0) |
                                                    (got[j].h - 1), msg);
          TEST_ASSERT_EQUAL_HEX16_MESSAGE(e.w2, (x << 5) & 0x3fe0, msg);
          TEST_ASSERT_EQUAL_HEX16_MESSAGE(e.code >> 11, PAL[s.type - 7], msg);
        }
        drawn += n != 0;
      }
    }
  }
  printf("mini objects: %u mini ticks drawn, %u dropped (OBJS full)\n", drawn, dropped);
  TEST_ASSERT_TRUE(drawn > 0);
}

// ---------------------------------------------------------------- race start path

// machine race start (marble.cpp beginRace) on a cleared work RAM
static void beginRace(uint8_t race) {
  memset(ram, 0, sizeof(ram));
  Mem m(ram, race);
  marble_physics::startRace(m, race);
  marble_camera::start(m, race);
  marble_physics::project(m);
  marble_occlusion::enter(m, PLAYER);
}

// live mini <=> exactly one draw list entry of its type
static void checkListed(const Mem &m, uint8_t race, int16_t cam) {
  for (uint8_t i = 0; i < marble_enemies::NMINIS; i++) {
    const uint32_t a = mini(i);
    const uint8_t want = m.rb(a + SLOT) ? 1 : 0;
    if (listedCount(m, m.rb(a + N_TYPE), i) == want) { continue; }
    char msg[80];
    snprintf(msg, sizeof(msg), "race %d cam %d: mini %d live %d, draw list differs", race, cam, i,
             want);
    TEST_FAIL_MESSAGE(msg);
  }
}

// Race sweep (marble_mini.py sweep): race start, then the camera over the whole race in 4 line
// steps, back, again, player idle; every enemy runs each tick. All nine live exactly while the
// silly band is in 0x1d-0x38 (2 spawns, the race start counted, 2 clears), never elsewhere, a
// draw list entry iff live, objects within OBJS.
static void test_race_sweep(void) {
  for (uint8_t race = 0; race < RACES; race++) {
    beginRace(race);
    Mem m(ram, race);
    const int16_t top = (int16_t)m.romw(m.desc() + marble_physics::DESC_TOP);
    const int16_t range = (int16_t)m.romw(m.desc() + marble_physics::DESC_RANGE);
    const int16_t n = range / SWEEP_STEP + 1;
    uint8_t spawns = m.rb(mini(0) + SLOT), clears = 0;
    uint32_t tick = 0;
    for (uint8_t pass = 0; pass < 3; pass++) {
      for (int16_t j = 0; j < n; j++) {
        int16_t step = pass == 1 ? n - 1 - j : j;
        if (race == RACE_SILLY) { step = n - 1 - step; }
        const int16_t cam = top + SWEEP_STEP * step;
        const bool before = m.rb(mini(0) + SLOT) != 0;
        mainTick(m, 0, 0, (uint32_t)(int32_t)cam, ++tick);
        marble_video::VideoState v = {};
        TEST_ASSERT_TRUE(marble_drawlist::build(m, cam, 24, v) <= marble_video::OBJS);

        const int16_t band = (int16_t)(cam - top) >> 4;
        const bool want = race == RACE_SILLY && band >= BAND_LO && band <= BAND_HI;
        for (uint8_t i = 0; i < marble_enemies::NMINIS; i++) {
          TEST_ASSERT_EQUAL_UINT8_MESSAGE(want, m.rb(mini(i) + SLOT), "mini live against the band");
        }
        spawns += !before && want;
        clears += before && !want;
        checkListed(m, race, cam);
      }
    }
    char msg[60];
    snprintf(msg, sizeof(msg), "race %d: spawns, clears", race);
    TEST_ASSERT_EQUAL_UINT8_MESSAGE(race == RACE_SILLY ? 2 : 0, spawns, msg);
    TEST_ASSERT_EQUAL_UINT8_MESSAGE(race == RACE_SILLY ? 2 : 0, clears, msg);
  }
}

// The marble put on the first acid mini at the silly race start (field zone, field floor)
// collects it: kind 2, the collected anim, 500 + 0x285b0(14) points; a race switch then starts
// as from a cleared work RAM with no mini live.
static void test_collect_and_switch(void) {
  static const uint8_t FIELD_ZONE = 1;
  static const uint8_t FIRST_ACID = 6;
  beginRace(RACE_SILLY);
  Mem m(ram, RACE_SILLY);
  const uint32_t a = mini(FIRST_ACID);
  TEST_ASSERT_EQUAL_UINT8(1, m.rb(a + SLOT));
  TEST_ASSERT_EQUAL_UINT8(ACID, m.rb(a + N_TYPE));

  m.wl(PLAYER + 0x00, 0);
  m.wl(PLAYER + 0x04, 0);
  m.wl(PLAYER + PX, m.rl(a + PX));
  m.wl(PLAYER + PY, m.rl(a + PY));
  m.wl(PLAYER + PZ, m.rl(a + PZ));
  m.wb(PLAYER + ZONE, FIELD_ZONE);
  const uint32_t score = m.rl(PLAYER + SCORE);
  const int16_t cam = m.sw(marble_physics::CAMERA);
  mainTick(m, 0, 0, (uint32_t)(int32_t)cam, 1);
  TEST_ASSERT_EQUAL_UINT8(COLLECTED, m.rb(a + N_KIND));
  TEST_ASSERT_TRUE(m.rl(PLAYER + SCORE) >= score + 500);
  checkListed(m, RACE_SILLY, cam);

  const uint8_t next = (RACE_SILLY + 1) % RACES;
  beginRace(next);
  static uint8_t clean[marble_physics::RAM_SIZE];
  memcpy(clean, ram, sizeof(ram));
  beginRace(next);
  TEST_ASSERT_EQUAL_MEMORY(clean, ram, sizeof(ram));
  Mem n(ram, next);
  for (uint8_t i = 0; i < marble_enemies::NMINIS; i++) {
    TEST_ASSERT_EQUAL_UINT8(i, n.rb(mini(i) + IDX));
    TEST_ASSERT_EQUAL_UINT8(0, n.rb(mini(i) + SLOT));
  }
}
#endif

int main(int argc, char **argv) {
  UNITY_BEGIN();
#ifdef HAVE_ROM
  Arena::init();
  marble_physics::loadRom();
  RUN_TEST(test_replay_minis);
  RUN_TEST(test_mini_objects);
  RUN_TEST(test_race_sweep);
  RUN_TEST(test_collect_and_switch);
#endif
  return UNITY_END();
}
